  'about.hero.title': 'İstanbul’dan Bakü’ye, oradan dünyaya',
  'about.hero.subtitle': 'Teknoloji, insan deneyimi ve sektör bilgisini tek bir platformda buluşturan emlak ekosistemi.',
  'about.s1.kicker': 'Hikayemiz',
  'about.s1.title': 'Hakkımızda',
  'about.s1.p1': 'ISTBAKU’nun hikayesi, yıllardır Türkiye’de yaşayan Azerbaycanlı bir girişimci gencin sektörde gördüklerinden doğdu. İstanbul’da emlakçılık yaparken fark edildi: platformlar pahalı ama verimsiz, teknoloji geride kalıyor, kullanıcıların gerçek ihtiyaçları çoğu zaman görünmüyor bile. Bu boşluğu doldurmak için ISTBAKU kuruldu.',
  'about.s1.p2': 'İsmin hikayesi tesadüf değil. IST İstanbul’u, BAKU ise Bakü’yü temsil ediyor. Azerbaycan ve Türkiye pazarında başlayıp altyapıyı tam oturttuktan sonra belirlenen ülkelerde aynı güçle yola devam edilecek. Sektörün içinden gelen bu bakış açısı, ISTBAKU’nun her özelliğine sinmiştir.',
  'about.s2.kicker': 'Ne için varız',
  'about.s2.title': 'Misyonumuz',
  'about.s2.p1': 'ISTBAKU’nun misyonu basit ama güçlüdür: emlak sürecinde yer alan herkesin işini doğru, verimli ve keyifle yapabileceği bir ortam kurmak. Alıcı, satıcı, emlakçı ve yatırımcı aynı sürecin farklı aktörleridir. ISTBAKU bu dört tarafı aynı platformda buluşturarak herkesin kendi rolünde en iyi şekilde hareket edebilmesini sağlar.',
  'about.s2.p2': 'Bunu yaparken teknoloji en güçlü aracımızdır. Yapay zeka destekli yatırım skoruyla yatırımcıya veriye dayalı kararlar aldırıyor, akıllı ilan asistanıyla emlakçının ilanını dakikalar içinde hazırlamasını sağlıyoruz. Tapu doğrulama ve onaylı ilan sistemiyle güven köprüsü kuruyor; takvim yönetimi, online rezervasyon ve güvenli ödeme ile günlük kiralama imkânı da sunuyoruz.',
  'about.s2.p3': 'Platformumuzda her ilan bir standarda tabidir. ISTBAKU Onaylı rozeti ve Gold Partner kriterleri yalnızca birer ödül değil; kaliteyi ölçülebilir kılan bir güven mimarisidir. Bu platformu aceleyle değil, doğruyu bilerek tasarladık. Çünkü iyi bir yazılım değil, gerçekten işe yarayan bir sistem kurmak istiyoruz.',
  'about.s3.kicker': 'Nereye gidiyoruz',
  'about.s3.title': 'Vizyonumuz',
  'about.s3.p1': 'ISTBAKU, emlak dünyasını yeniden tanımlamak için kuruldu. Bir ilanı listelemek artık yeterli değil. Yatırımcı doğru kararı verebilmeli, emlakçı güvenle çalışabilmeli, alıcı ise süreci şeffaf ve kolay bir şekilde tamamlayabilmelidir.',
  'about.s3.p2': 'Türkiye ve Azerbaycan’dan dünyaya uzanan bu yolculukta vizyonumuz nettir: dünyanın her ülkesinde tanınan, güvenilen ve tercih edilen bir emlak platformu olmak. Teknolojiyi, insan deneyimini ve sektör bilgisini tek bir platformda bir araya getiriyoruz.',
  'about.s3.p3': 'Her yeni ülkede, o ülkenin kültürünü ve dinamiklerini içselleştirerek büyüyoruz. ISTBAKU; yatırımcının en güvendiği adres, emlakçının en güçlü iş ortağı, alıcının ise en doğru rehberi olmayı hedefler. Bugün iki ülkede attığımız bu adım, yarın tüm dünyada hissedilecek.',

