  'about.hero.title': 'İstanbuldan Bakıya, oradan dünyaya',
  'about.hero.subtitle': 'Texnologiya, insan təcrübəsi və sektor biliyini vahid platformada birləşdirən əmlak ekosistemi.',
  'about.s1.kicker': 'Hekayəmiz',
  'about.s1.title': 'Haqqımızda',
  'about.s1.p1': 'ISTBAKU-nun hekayəsi uzun illər Türkiyədə yaşayan azərbaycanlı bir gənc sahibkarın sektorda gördüklərindən doğdu. İstanbulda əmlak işi ilə məşğul olarkən görüldü: platformalar bahalı, lakin səmərəsizdir, texnologiya geri qalır, istifadəçilərin əsl ehtiyacları çox zaman görünmür belə. Bu boşluğu doldurmaq üçün ISTBAKU quruldu.',
  'about.s1.p2': 'Adın hekayəsi təsadüf deyil. IST İstanbulu, BAKU isə Bakını təmsil edir. Azərbaycan və Türkiyə bazarında başlayıb infrastruktur tam oturduqdan sonra müəyyən ölkələrdə eyni güclə yola davam ediləcək. Sektorun içindən gələn bu baxış ISTBAKU-nun hər xüsusiyyətində əks olunub.',
  'about.s2.kicker': 'Nə üçün varıq',
  'about.s2.title': 'Missiyamız',
  'about.s2.p1': 'ISTBAKU-nun missiyası sadə, lakin güclüdür: əmlak prosesində iştirak edən hər kəsin işini düzgün, səmərəli və həvəslə görə biləcəyi bir mühit qurmaq. Alıcı, satıcı, vasitəçi və investor eyni prosesin müxtəlif iştirakçılarıdır. ISTBAKU bu dörd tərəfi eyni platformada birləşdirir.',
  'about.s2.p2': 'Bunu edərkən texnologiya ən güclü alətimizdir. Süni intellekt dəstəkli investisiya balı ilə investora dataya əsaslanan qərarlar verdiririk, ağıllı elan asistenti ilə vasitəçinin elanını dəqiqələr içində hazırlamasını təmin edirik. Çıxarış doğrulaması və təsdiqli elan sistemi ilə etibar körpüsü qururuq; təqvim idarəetməsi, onlayn rezervasiya və təhlükəsiz ödəniş ilə gündəlik icarə imkanı da təklif edirik.',
  'about.s2.p3': 'Platformamızda hər elan bir standarta tabedir. ISTBAKU Təsdiqli nişanı və Gold Partner meyarları yalnız mükafat deyil; keyfiyyəti ölçüləbilən edən etibar memarlığıdır. Bu platformanı tələsik deyil, doğrunu bilərək hazırladıq.',
  'about.s3.kicker': 'Hara gedirik',
  'about.s3.title': 'Vizyonumuz',
  'about.s3.p1': 'ISTBAKU əmlak dünyasını yenidən təyin etmək üçün quruldu. Bir elanı yerləşdirmək artıq kifayət deyil. İnvestor düzgün qərar verə bilməli, vasitəçi etibarla işləyə bilməli, alıcı isə prosesi şəffaf və asan tamamlaya bilməlidir.',
  'about.s3.p2': 'Türkiyə və Azərbaycandan dünyaya uzanan bu yolda vizyonumuz aydındır: dünyanın hər ölkəsində tanınan, etibar edilən və seçilən bir əmlak platforması olmaq. Texnologiyanı, insan təcrübəsini və sektor biliyini vahid platformada birləşdiririk.',
  'about.s3.p3': 'Hər yeni ölkədə onun mədəniyyətini və dinamikasını mənimsəyərək böyüyürük. ISTBAKU investorun ən etibar etdiyi ünvan, vasitəçinin ən güclü iş ortağı, alıcının isə ən doğru bələdçisi olmağı hədəfləyir.',

