  'about.hero.title': 'From Istanbul to Baku, and on to the world',
  'about.hero.subtitle': 'A real-estate ecosystem that unites technology, human experience and industry know-how on a single platform.',
  'about.s1.kicker': 'Our Story',
  'about.s1.title': 'About Us',
  'about.s1.p1': 'ISTBAKU was born from what a young Azerbaijani entrepreneur — living in Türkiye for years — saw in the industry. While working in real estate in Istanbul, it became clear: platforms were expensive yet inefficient, technology lagged behind, and users’ real needs were often invisible. ISTBAKU was founded to fill that gap.',
  'about.s1.p2': 'The name is no coincidence. IST stands for Istanbul, BAKU for Baku. We start in the Azerbaijani and Turkish markets and, once the foundation is firmly in place, continue into selected countries with the same strength. This industry-insider perspective runs through every feature of ISTBAKU.',
  'about.s2.kicker': 'Why we exist',
  'about.s2.title': 'Our Mission',
  'about.s2.p1': 'ISTBAKU’s mission is simple but powerful: to build an environment where everyone in the real-estate process can work accurately, efficiently and with pleasure. Buyer, seller, agent and investor are different actors in the same process. ISTBAKU brings these four sides onto one platform so each can perform at their best.',
  'about.s2.p2': 'Technology is our strongest tool. With an AI-powered investment score we help investors make data-driven decisions, and with a smart listing assistant agents prepare listings in minutes. Through deed verification and a verified-listing system we build a bridge of trust; with calendar management, online booking and secure payments we also enable short-term rentals.',
  'about.s2.p3': 'Every listing meets a standard. The ISTBAKU Approved badge and Gold Partner criteria are not just awards but a trust architecture that makes quality measurable. We designed this platform deliberately, not in haste — because we want to build a system that truly works, not just good software.',
  'about.s3.kicker': 'Where we are going',
  'about.s3.title': 'Our Vision',
  'about.s3.p1': 'ISTBAKU was founded to redefine real estate. Listing a property is no longer enough. The investor must be able to make the right decision, the agent must work with confidence, and the buyer must complete the process transparently and easily.',
  'about.s3.p2': 'On this journey from Türkiye and Azerbaijan to the world, our vision is clear: to become a real-estate platform recognized, trusted and preferred in every country. We bring technology, human experience and industry knowledge together on a single platform.',
  'about.s3.p3': 'In every new country we grow by internalizing its culture and dynamics. ISTBAKU aims to be the investor’s most trusted address, the agent’s strongest partner, and the buyer’s most reliable guide. The step we take today in two countries will be felt worldwide tomorrow.',

