const DICTS: Record<Lang, Dict> = { tr, az, en, ru, de, zh };

export function t(key: string, lang: Lang = DEFAULT_LANG): string {
  return DICTS[lang]?.[key] ?? DICTS.tr[key] ?? key;
}
